from pathlib import Path
import json
p = Path('world/pages')
ids = {'SQLITE-COMMUNITY-DIRECTORY-FIT', 'SQLITE-BESPOKE-QUOTE-TERMS', 'SQLITE-INBOUND-BESPOKE-DIAGNOSIS', 'SQLITE-ORIGINAL-FIXTURE-SELLER-PACKAGE'}
found = {}
def walk(obj):
    if isinstance(obj, dict):
        if obj.get('mission_id') in ids and 'status' in obj:
            found[obj['mission_id']] = {k: obj.get(k) for k in ('status', 'agent_id', 'lease_expires_at', 'evidence')}
        for v in obj.values():
            walk(v)
    elif isinstance(obj, list):
        for v in obj:
            walk(v)
for f in sorted(p.glob('missions-*.json')):
    walk(json.loads(f.read_text()))
print(json.dumps({'missions': found, 'missing_from_selected_pages': sorted(ids - found.keys())}))
